import{_ as a,o as n,c as e,a6 as i}from"./chunks/framework.BBIckNDn.js";const u=JSON.parse('{"title":"判断ガイド: イベントを使うべきか・依存性注入を使うべきか・Singletonを許容できるか","description":"","frontmatter":{"title":"判断ガイド: イベントを使うべきか・依存性注入を使うべきか・Singletonを許容できるか","study":{"source":"C++ Wiki","kind":"本文","status":"既存原稿","summary":"使わない場面: 因果を追いたいコアロジック、1フレームの遅延が致命的な判定、隣のクラスを呼ぶだけの場面 トレードオフ: 疎結合 ⇔ 制御フローの不可視化(「なぜ起きた」が追えないコードは疎結合の失敗形)"}},"headers":[],"relativePath":"design/decisions/events-di-singleton.md","filePath":"design/decisions/events-di-singleton.md"}'),t={name:"design/decisions/events-di-singleton.md"};function l(p,s,o,r,d,c){return n(),e("div",null,[...s[0]||(s[0]=[i(`<h1 id="判断ガイド-イベントを使うべきか・依存性注入を使うべきか・singletonを許容できるか" tabindex="-1">判断ガイド: イベントを使うべきか・依存性注入を使うべきか・Singletonを許容できるか <a class="header-anchor" href="#判断ガイド-イベントを使うべきか・依存性注入を使うべきか・singletonを許容できるか" aria-label="Permalink to &quot;判断ガイド: イベントを使うべきか・依存性注入を使うべきか・Singletonを許容できるか&quot;">​</a></h1><h2 id="イベント-observer-queue-bus-を使うべきか" tabindex="-1">イベント(Observer/Queue/Bus)を使うべきか <a class="header-anchor" href="#イベント-observer-queue-bus-を使うべきか" aria-label="Permalink to &quot;イベント(Observer/Queue/Bus)を使うべきか&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Q1. その処理は「ルールの帰結」か「観測」か「演出」か?([イベント通知の3分類](../11_case_studies/14_event_notification.md))</span></span>
<span class="line"><span>    → ルールの帰結(順序・確実性が仕様)──&gt; イベントにしない。直接呼び出しで順序を固定</span></span>
<span class="line"><span>    → 観測(実績・統計・クエスト)──&gt; Pub/Sub</span></span>
<span class="line"><span>    → 演出(UI・音)──&gt; Event Queue(遅延+集約)</span></span>
<span class="line"><span>Q2. 反応者は複数か、増えるか?</span></span>
<span class="line"><span>    → 1つで固定 ──&gt; コールバック1本か直接呼び出しで十分</span></span>
<span class="line"><span>Q3. 発行者は反応者を知り得る立場か?</span></span>
<span class="line"><span>    → 知っていて自然(同一画面の部品)──&gt; [Mediator](../03_design_patterns/mediator.md)や直接参照</span></span>
<span class="line"><span>    → 知るべきでない(層をまたぐ)──&gt; イベント</span></span></code></pre></div><ul><li><strong>使わない場面</strong>: 因果を追いたいコアロジック、1フレームの遅延が致命的な判定、隣のクラスを呼ぶだけの場面</li><li>トレードオフ: 疎結合 ⇔ 制御フローの不可視化(「なぜ起きた」が追えないコードは疎結合の失敗形)</li></ul><h2 id="依存性注入-di-を使うべきか" tabindex="-1">依存性注入(DI)を使うべきか <a class="header-anchor" href="#依存性注入-di-を使うべきか" aria-label="Permalink to &quot;依存性注入(DI)を使うべきか&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Q1. その依存を差し替えたいか?(テスト・プラットフォーム・設定)</span></span>
<span class="line"><span>    → いいえ、永遠に1実装 ──&gt; 直接使う(newも直書きでよい)</span></span>
<span class="line"><span>Q2. 差し替えたい → 注入方法を選ぶ</span></span>
<span class="line"><span>    → 依存が少数(〜4個)──&gt; コンストラクタ手渡し(これもDI。コンテナ不要)</span></span>
<span class="line"><span>    → MonoBehaviour等でコンストラクタ不可 ──&gt; SerializeField/初期化メソッド注入</span></span>
<span class="line"><span>    → オブジェクトグラフが巨大で手動配線が苦痛 ──&gt; DIコンテナ(最後の手段)</span></span>
<span class="line"><span>Q3. コンストラクタ引数が6個を超えた?</span></span>
<span class="line"><span>    → 依存が多すぎるサイン。注入方法ではなく[クラスの分割](01_split_class.md)を先に検討</span></span></code></pre></div><ul><li>根拠: <a href="/study/game/patterns/service-locator-and-di.html">Service LocatorとDI</a>、<a href="/study/design/solid/dip.html">DIP</a></li><li>トレードオフ: 依存の可視化・テスト容易性 ⇔ 配線コード。<strong>「DIコンテナ導入=DI」ではない</strong>(手渡しが基本形)</li></ul><h2 id="singletonを許容できるか" tabindex="-1">Singletonを許容できるか <a class="header-anchor" href="#singletonを許容できるか" aria-label="Permalink to &quot;Singletonを許容できるか&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Q1. 状態を持つか?</span></span>
<span class="line"><span>    → ほぼ無状態(ログ、数学、読み取り専用設定)──&gt; 許容しやすい。namespaceの自由関数も検討</span></span>
<span class="line"><span>    → 可変状態を持つ(進行状況、プレイヤーデータ)──&gt; Q2へ</span></span>
<span class="line"><span>Q2. その状態を読み書きする箇所は全域に散っているか?</span></span>
<span class="line"><span>    → 散らばる予定 ──&gt; 危険信号。所有者を決めて引数/注入で配る設計に戻す</span></span>
<span class="line"><span>Q3. テストで差し替え・リセットが必要か?</span></span>
<span class="line"><span>    → 必要 ──&gt; Singletonをやめるか、[Service Locator](../04_game_patterns/service_locator_and_di.md)(差し替え可能な中間形)へ</span></span>
<span class="line"><span>Q4. それでもSingletonにするなら:</span></span>
<span class="line"><span>    ・生成/破棄タイミングを明示(Startup/Shutdown方式)([初期化順問題](../07_memory_and_runtime/01_storage_duration_and_lifetime.md)の回避)</span></span>
<span class="line"><span>    ・書き込みAPIを絞る(読み取りは広く、書き込みは狭く)</span></span>
<span class="line"><span>    ・「なぜ許容したか」をコメントに残す</span></span></code></pre></div><ul><li>根拠: <a href="/study/design/patterns/singleton.html">Singleton</a>。UEなら<a href="/study/game/unreal/gameplay-framework.html">Subsystem</a>という公式の中間解がある</li><li>トレードオフ: アクセスの手軽さ ⇔ 隠れ依存・テスト困難・神クラス化。<strong>「便利」は総コストの前借り</strong></li></ul><h2 id="_3つに共通する判断軸" tabindex="-1">3つに共通する判断軸 <a class="header-anchor" href="#_3つに共通する判断軸" aria-label="Permalink to &quot;3つに共通する判断軸&quot;">​</a></h2><p>いずれも「<strong>結合を見えなくする道具</strong>」(イベント=呼び出しを、DI=生成を、Singleton=依存を隠す)。隠してよいのは「知るべきでないもの」だけで、<strong>知るべきもの(順序・所有・依存)を隠すと必ず後で払う</strong>——これがこのページ全体の要約です。</p><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li>「ルールの帰結をイベントにしない」理由は?</li><li>DIコンテナが「最後の手段」である理由は?</li><li>Singleton許容の条件(状態・範囲・テスト)を言えますか。</li></ol><hr><p>前: <a href="/study/design/decisions/abstraction-and-patterns.html">抽象化・パターンの判断</a> | <a href="/study/design/decisions/">カテゴリ目次</a> | 次: <a href="/study/design/decisions/cpp-choices.html">C++の選択</a></p>`,16)])])}const h=a(t,[["render",l]]);export{u as __pageData,h as default};
